import type { KeyboardDef } from '../model/types'
// Generated by `node scripts/gen-keyboards.mjs <zmk-clone>` from ZMK v0.3.
import keyboards from './keyboards.json'

// Encoder push switches that sit in the key matrix. ZMK's physical layouts don't mark them,
// so they are listed by hand (positions checked against each board's stock keymap).
const ENCODER_KEYS: Record<string, (number | null)[]> = {
  sofle: [42, 43],
  splitkb_aurora_sofle: [42, 43],
  lotus58: [44, 45],
}

export const KEYBOARDS: KeyboardDef[] = (keyboards as KeyboardDef[]).map((k) =>
  ENCODER_KEYS[k.id] ? { ...k, encoderKeys: ENCODER_KEYS[k.id] } : k,
)

/** encoder index whose push switch is key `pos`, if any */
export function encoderAtKey(kb: KeyboardDef, pos: number): number | undefined {
  const i = kb.encoderKeys?.indexOf(pos) ?? -1
  return i >= 0 ? i : undefined
}

const byId = new Map(KEYBOARDS.map((k) => [k.id, k]))

export function getKeyboard(id: string): KeyboardDef | undefined {
  return byId.get(id)
}

/** Interconnect (footprint) a controller board exposes. Shields here mostly require pro_micro. */
export type Interconnect = 'pro_micro' | 'seeed_xiao' | 'makerdiary_nrf52840_m2'

